 28→function request(method, urlPath, body, token) {
 29→  return new Promise((resolve, reject) => {
 30→    const options = {
 31→      method,
 32→      hostname: 'localhost',
 33→      port: PORT,
 34→      path: urlPath,
 35→      headers: {},
 36→    };
 37→    if (token) options.headers['Authorization'] = `Bearer ${token}`;
 38→    if (body) options.headers['Content-Type'] = 'application/json';
 39→
 40→    const req = http.request(options, (res) => {
 41→      let data = '';
 42→      res.on('data', (chunk) => (data += chunk));
 43→      res.on('end', () => {
 44→        let json;
 45→        try {
 46→          json = JSON.parse(data);
 47→        } catch {
 48→          json = data;
 49→        }
 50→        resolve({ status: res.statusCode, body: json });
 51→      });
 52→    });
 53→    req.on('error', reject);
 54→    if (body) req.write(JSON.stringify(body));
 55→    req.end();
 56→  });
 57→}
 58→
 59→function post(urlPath, body, token) {
 60→  return request('POST', urlPath, body, token);
 61→}
 62→
 63→function get(urlPath, token) {
 64→  return request('GET', urlPath, null, token);
 65→}
