 67→function connectWs(roomId, token) {
 68→  // Use raw HTTP upgrade to avoid needing ws client in the test runner
 69→  return new Promise((resolve, reject) => {
 70→    const WebSocket = require('ws');
 71→    const ws = new WebSocket(
 72→      `ws://localhost:${PORT}/api/rooms/${roomId}/ws?token=${token}`
 73→    );
 74→    const messages = [];
 75→    ws.on('open', () => {});
 76→    ws.on('message', (data) => {
 77→      messages.push(JSON.parse(data.toString()));
 78→    });
 79→    ws.on('error', (err) => reject(err));
 80→    // Resolve after first message (joined event)
 81→    ws.once('message', () => {
 82→      setTimeout(() => resolve({ ws, messages }), 50);
 83→    });
 84→  });
 85→}
