 87→function connectWsRaw(roomId, token) {
 88→  return new Promise((resolve) => {
 89→    const req = http.request({
 90→      hostname: 'localhost',
 91→      port: PORT,
 92→      path: `/api/rooms/${roomId}/ws?token=${token}`,
 93→      headers: {
 94→        Connection: 'Upgrade',
 95→        Upgrade: 'websocket',
 96→        'Sec-WebSocket-Version': '13',
 97→        'Sec-WebSocket-Key': 'dGVzdA==',
 98→      },
 99→    });
100→    req.on('upgrade', () => resolve({ upgraded: true }));
101→    req.on('response', (res) => resolve({ upgraded: false, status: res.statusCode }));
102→    req.on('error', () => resolve({ upgraded: false, status: 0 }));
103→    req.end();
104→  });
