  6→import AuthGate from './components/AuthGate';
  7→import { createGame, saveGame, loadGame, markGamePublished, setCurrentUser } from './utils/gameManager';
  8→import { usePasskeyAuth } from './hooks/usePasskeyAuth';
  9→import { usePasskeyPublish } from './hooks/usePasskeyPublish';
 10→
 11→function App() {
 12→  const [view, setView] = useState('list'); // 'list' | 'setup' | 'playing'
 13→  const [activeGame, setActiveGame] = useState(null);
 14→  const [setupColor, setSetupColor] = useState('white');
 15→  const [publishStatus, setPublishStatus] = useState(null); // null | 'pending' | 'success' | 'error'
 16→
 17→  const passkey = usePasskeyAuth();
 18→  const { publishGame: passkeyPublish } = usePasskeyPublish({
 19→    account: passkey.account,
 20→    credentialId: passkey.credentialId,
 21→    rawId: passkey.rawId,
 22→  });
 23→
 24→  // Scope game storage to the authenticated user
 25→  useEffect(() => {
 26→    if (passkey.isAuthenticated && passkey.account) {
 27→      setCurrentUser(passkey.account);
 28→    } else {
 29→      setCurrentUser(null);
 30→    }
 31→  }, [passkey.isAuthenticated, passkey.account]);
 32→
 33→  const handleLogout = () => {
 34→    passkey.logout();
 35→    setActiveGame(null);
 36→    setPublishStatus(null);
 37→    setView('list');
 38→  };
 39→
 40→  const handleNewGame = () => {
 41→    setView('setup');
 42→  };
 43→
 44→  const handleStartGame = () => {
 45→    const engineColor = setupColor === 'white' ? 'black' : 'white';
 46→    const game = createGame(engineColor);
 47→    setActiveGame(game);
 48→    setView('playing');
 49→  };
 50→
 51→  const handleResumeGame = (gameId) => {
 52→    const game = loadGame(gameId);
 53→    if (game) {
 54→      setActiveGame(game);
 55→      setView('playing');
 56→    }
 57→  };
 58→
 59→  const handleSave = (state) => {
 60→    if (!activeGame) return;
 61→    saveGame({ ...state, id: activeGame.id, engineColor: activeGame.engineColor, createdAt: activeGame.createdAt });
 62→  };
 63→
 64→  const handleGameEnd = async (result) => {
 65→    if (!activeGame) return;
 66→
 67→    const latestState = loadGame(activeGame.id);
 68→    if (latestState) {
 69→      latestState.result = result;
 70→      saveGame(latestState);
 71→    }
 72→    setActiveGame(prev => ({ ...prev, result }));
 73→
 74→    const finishedGame = latestState || { ...activeGame, result };
 75→
 76→    setPublishStatus('pending');
 77→    const publishResult = await passkeyPublish(finishedGame);
 78→
 79→    if (publishResult.published) {
 80→      setPublishStatus('success');
 81→      markGamePublished(finishedGame.id, publishResult.txHash);
 82→      setTimeout(() => setPublishStatus(null), 4000);
 83→    } else if (['no-contract-address', 'passkey-not-authenticated'].includes(publishResult.reason)) {
 84→      setPublishStatus(null);
 85→    } else {
 86→      setPublishStatus('error');
 87→      setTimeout(() => setPublishStatus(null), 5000);
 88→    }
 89→  };
 90→
 91→  const handleBackToList = () => {
 92→    setActiveGame(null);
 93→    setPublishStatus(null);
 94→    setView('list');
 95→  };
 96→
 97→  // Unauthenticated: show auth gate only
 98→  if (!passkey.isAuthenticated) {
 99→    return <AuthGate onSignup={passkey.signup} onLogin={passkey.login} />;
100→  }
101→
102→  return (
103→    <div className="app">
104→      <header className="app-header">
105→        <h1>Chess Board</h1>
106→        <div className="passkey-status">
107→          <span className="passkey-badge" title={passkey.account}>
108→            {passkey.username || passkey.account?.slice(0, 6) + '...' + passkey.account?.slice(-4)}
109→          </span>
110→          <button className="passkey-logout" onClick={handleLogout}>Logout</button>
111→        </div>
112→      </header>
113→
114→      {publishStatus && (
115→        <div className={`publish-toast ${publishStatus}`}>
116→          {publishStatus === 'pending' && 'Publishing game on-chain...'}
117→          {publishStatus === 'success' && 'Game published on-chain!'}
118→          {publishStatus === 'error' && 'Failed to publish on-chain'}
119→        </div>
120→      )}
121→
122→      {view === 'list' && (
123→        <GameList onNewGame={handleNewGame} onResumeGame={handleResumeGame} />
124→      )}
125→
126→      {view === 'setup' && (
127→        <div className="new-game-setup">
128→          <h2>New Game</h2>
129→          <div className="color-picker">
130→            <label>Play as:</label>
131→            <div className="color-options">
132→              <button
133→                className={`color-option ${setupColor === 'white' ? 'selected' : ''}`}
134→                onClick={() => setSetupColor('white')}
135→              >
136→                White
137→              </button>
138→              <button
139→                className={`color-option ${setupColor === 'black' ? 'selected' : ''}`}
140→                onClick={() => setSetupColor('black')}
141→              >
142→                Black
143→              </button>
144→            </div>
145→          </div>
146→          <div className="setup-actions">
147→            <button className="setup-back" onClick={() => setView('list')}>Cancel</button>
148→            <button className="setup-start" onClick={handleStartGame}>Start Game</button>
149→          </div>
150→        </div>
151→      )}
152→
153→      {view === 'playing' && activeGame && (
154→        <Chessboard
155→          key={activeGame.id}
156→          initialState={activeGame}
157→          onSave={handleSave}
158→          onGameEnd={handleGameEnd}
159→          onBackToList={handleBackToList}
160→          engineColorProp={activeGame.engineColor}
161→        />
162→      )}
163→    </div>
164→  );
165→}
166→
167→export default App;
