 10→function bufToHex(buf) {
 11→  return '0x' + Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
 12→}
 13→
 14→function base64urlEncode(buf) {
 15→  return btoa(String.fromCharCode(...new Uint8Array(buf)))
 16→    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
 17→}
 18→
 19→function base64urlDecode(str) {
 20→  str = str.replace(/-/g, '+').replace(/_/g, '/');
 21→  while (str.length % 4) str += '=';
 22→  const binary = atob(str);
 23→  const bytes = new Uint8Array(binary.length);
 24→  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
 25→  return bytes.buffer;
 26→}
