 4→export default function AuthGate({ onSignup, onLogin }) {
 5→  const [mode, setMode] = useState(null); // null | 'signup' | 'login'
 6→  const [username, setUsername] = useState('');
 7→  const [loading, setLoading] = useState(false);
 8→  const [error, setError] = useState(null);
 9→
10→  const handleSignup = async (e) => {
11→    e.preventDefault();
12→    if (!username.trim()) return;
13→    setLoading(true);
14→    setError(null);
15→    try {
