17→    } catch (err) {
18→      setError(err.message);
19→      setLoading(false);
20→    }
21→  };
22→
23→  const handleLogin = async () => {
24→    setLoading(true);
25→    setError(null);
26→    try {
27→      await onLogin();
28→    } catch (err) {
29→      setError(err.message || 'Login failed. Do you have an account? Try signing up.');
30→      setLoading(false);
31→    }
32→  };
