129→    });
130→
131→    const timeout = setTimeout(() => {
132→      reject(new Error('Server did not start within 5s'));
133→    }, 5000);
134→
135→    serverProcess.stdout.on('data', (data) => {
136→      const text = data.toString();
137→      if (text.includes('listening')) {
138→        clearTimeout(timeout);
139→        resolve();
140→      }
141→    });
142→
143→    serverProcess.stderr.on('data', (data) => {
144→      // Suppress server stderr unless debugging
145→    });
146→
147→    serverProcess.on('error', (err) => {
148→      clearTimeout(timeout);
149→      reject(err);
150→    });
151→  });
