 28→export function usePasskeyAuth() {
 29→  const [isAuthenticated, setIsAuthenticated] = useState(false);
 30→  const [account, setAccount] = useState(null);
 31→  const [username, setUsername] = useState(null);
 32→  const [credentialId, setCredentialId] = useState(null);
 33→  const [rawId, setRawId] = useState(null);
 34→
 35→  // Restore session from localStorage on mount
 36→  useEffect(() => {
 37→    const storedCredId = localStorage.getItem(LS_KEYS.credentialId);
 38→    const storedRawId = localStorage.getItem(LS_KEYS.rawId);
 39→    const storedAccount = localStorage.getItem(LS_KEYS.account);
 40→    if (storedCredId && storedRawId && storedAccount) {
 41→      const parsed = JSON.parse(storedAccount);
 42→      setCredentialId(storedCredId);
 43→      setRawId(base64urlDecode(storedRawId));
 44→      setAccount(parsed.address);
 45→      setUsername(parsed.username);
 46→      setIsAuthenticated(true);
 47→    }
 48→  }, []);
 49→
 50→  const persistSession = useCallback((credId, rawIdBuf, address, user) => {
 51→    localStorage.setItem(LS_KEYS.credentialId, credId);
 52→    localStorage.setItem(LS_KEYS.rawId, base64urlEncode(rawIdBuf));
 53→    localStorage.setItem(LS_KEYS.account, JSON.stringify({ address, username: user }));
 54→    setCredentialId(credId);
 55→    setRawId(rawIdBuf);
 56→    setAccount(address);
 57→    setUsername(user);
 58→    setIsAuthenticated(true);
 59→  }, []);
 60→
 61→  const signup = useCallback(async (name) => {
 62→    if (!name || !name.trim()) throw new Error('Username required');
 63→    const trimmed = name.trim();
 64→
 65→    // 1. Create passkey credential
 66→    const challenge = crypto.getRandomValues(new Uint8Array(32));
 67→    const credential = await navigator.credentials.create({
 68→      publicKey: {
 69→        rp: { name: 'Login.com Smart Account', id: location.hostname },
 70→        user: {
 71→          id: crypto.getRandomValues(new Uint8Array(16)),
 72→          name: trimmed,
 73→          displayName: trimmed,
 74→        },
 75→        challenge,
 76→        pubKeyCredParams: [{ type: 'public-key', alg: -7 }], // ES256 = P-256
 77→        authenticatorSelection: {
 78→          authenticatorAttachment: 'platform',
 79→          residentKey: 'required',
 80→          userVerification: 'preferred',
 81→        },
 82→        timeout: 60000,
 83→      },
 84→    });
 85→
 86→    // 2. Extract public key (X, Y)
 87→    const publicKeyBytes = new Uint8Array(credential.response.getPublicKey());
 88→    let rawKey;
 89→    if (publicKeyBytes.length === 65 && publicKeyBytes[0] === 0x04) {
 90→      rawKey = publicKeyBytes;
 91→    } else {
 92→      const spkiOffset = publicKeyBytes.length - 65;
 93→      rawKey = publicKeyBytes.slice(spkiOffset);
 94→    }
 95→    if (rawKey[0] !== 0x04) throw new Error('Expected uncompressed public key (0x04 prefix)');
 96→
 97→    const pubKeyX = bufToHex(rawKey.slice(1, 33));
 98→    const pubKeyY = bufToHex(rawKey.slice(33, 65));
 99→    const credId = base64urlEncode(credential.rawId);
100→
101→    // 3. Register on server (deploys smart account)
102→    const resp = await fetch(`${API_BASE}/api/register`, {
103→      method: 'POST',
104→      headers: { 'Content-Type': 'application/json' },
105→      body: JSON.stringify({ credentialId: credId, pubKeyX, pubKeyY, username: trimmed }),
106→    });
107→    const data = await resp.json();
108→    if (!resp.ok) throw new Error(data.error || 'Registration failed');
109→
110→    // 4. Persist session
111→    persistSession(credId, credential.rawId, data.address, trimmed);
112→    return { address: data.address, txHash: data.txHash };
113→  }, [persistSession]);
114→
115→  const login = useCallback(async () => {
116→    // 1. Discoverable credential assertion
117→    const challenge = crypto.getRandomValues(new Uint8Array(32));
118→    const assertion = await navigator.credentials.get({
119→      publicKey: {
120→        challenge,
121→        rpId: location.hostname,
122→        allowCredentials: [],
123→        userVerification: 'preferred',
124→        timeout: 60000,
125→      },
126→    });
127→
128→    const credId = base64urlEncode(assertion.rawId);
129→
130→    // 2. Look up account on server
131→    const resp = await fetch(`${API_BASE}/api/login`, {
132→      method: 'POST',
133→      headers: { 'Content-Type': 'application/json' },
134→      body: JSON.stringify({ credentialId: credId }),
135→    });
136→    const data = await resp.json();
137→    if (!resp.ok) throw new Error(data.error || 'Login failed');
138→
139→    // 3. Persist session
140→    persistSession(credId, assertion.rawId, data.accountAddress, data.username);
141→    return { address: data.accountAddress, username: data.username };
142→  }, [persistSession]);
143→
144→  const logout = useCallback(() => {
145→    localStorage.removeItem(LS_KEYS.credentialId);
146→    localStorage.removeItem(LS_KEYS.rawId);
147→    localStorage.removeItem(LS_KEYS.account);
148→    setCredentialId(null);
149→    setRawId(null);
150→    setAccount(null);
151→    setUsername(null);
152→    setIsAuthenticated(false);
153→  }, []);
154→
155→  return { isAuthenticated, account, username, credentialId, rawId, signup, login, logout };
156→}
