 31→// --- FEN generation (ported from chessEngine.js) ---
 32→
 33→function boardToFEN(gameState) {
 34→  const { board, currentTurn, halfMoveClock, enPassantTarget, movedPieces } = gameState;
 35→  let fen = '';
 36→
 37→  // Piece placement
 38→  for (let row = 0; row < 8; row++) {
 39→    let emptyCount = 0;
 40→    for (let col = 0; col < 8; col++) {
 41→      const piece = board[row * 8 + col];
 42→      if (piece === 0) {
 43→        emptyCount++;
 44→      } else {
 45→        if (emptyCount > 0) {
 46→          fen += emptyCount;
 47→          emptyCount = 0;
 48→        }
 49→        fen += PIECE_TO_FEN[piece] || '?';
 50→      }
 51→    }
 52→    if (emptyCount > 0) {
 53→      fen += emptyCount;
 54→    }
 55→    if (row < 7) fen += '/';
 56→  }
 57→
 58→  // Active color
 59→  fen += ' ' + (currentTurn === COLORS.WHITE ? 'w' : 'b');
 60→
 61→  // Castling availability
 62→  let castling = '';
 63→  // White kingside: king on e1 (60) and rook on h1 (63) haven't moved
 64→  if (!movedPieces.has(60) && !movedPieces.has(63) && board[60] === PIECE_TYPES.KING && board[63] === PIECE_TYPES.ROOK) castling += 'K';
 65→  // White queenside: king on e1 (60) and rook on a1 (56) haven't moved
 66→  if (!movedPieces.has(60) && !movedPieces.has(56) && board[60] === PIECE_TYPES.KING && board[56] === PIECE_TYPES.ROOK) castling += 'Q';
 67→  // Black kingside: king on e8 (4) and rook on h8 (7) haven't moved
 68→  if (!movedPieces.has(4) && !movedPieces.has(7) && board[4] === -PIECE_TYPES.KING && board[7] === -PIECE_TYPES.ROOK) castling += 'k';
 69→  // Black queenside: king on e8 (4) and rook on a8 (0) haven't moved
 70→  if (!movedPieces.has(4) && !movedPieces.has(0) && board[4] === -PIECE_TYPES.KING && board[0] === -PIECE_TYPES.ROOK) castling += 'q';
 71→  fen += ' ' + (castling || '-');
 72→
 73→  // En passant target
 74→  fen += ' ' + (enPassantTarget !== null ? indexToAlgebraic(enPassantTarget) : '-');
 75→
 76→  // Halfmove clock
 77→  fen += ' ' + halfMoveClock;
 78→
 79→  // Fullmove number (derive from move history length)
 80→  const fullMove = Math.floor((gameState.moveHistory || []).length / 2) + 1;
 81→  fen += ' ' + fullMove;
 82→
 83→  return fen;
 84→}
 85→
 86→// --- Move parsing ---
 87→
 88→function parseMove(moveStr) {
 89→  if (!moveStr || typeof moveStr !== 'string') return null;
 90→
 91→  // Normalize: remove spaces, dashes, lowercase
 92→  const clean = moveStr.replace(/[\s\-]/g, '').toLowerCase();
 93→
 94→  // UCI format: e2e4, e7e8q (with optional promotion)
 95→  const uciMatch = clean.match(/^([a-h][1-8])([a-h][1-8])([qrbn])?$/);
 96→  if (uciMatch) {
 97→    return {
 98→      from: algebraicToIndex(uciMatch[1]),
 99→      to: algebraicToIndex(uciMatch[2]),
100→      promotion: uciMatch[3] || null
101→    };
102→  }
103→
104→  return null;
105→}
106→
107→// --- Move legality check ---
108→
109→function isMoveLegal(gameState, from, to, promotion) {
110→  const { board, currentTurn, enPassantTarget, movedPieces } = gameState;
111→  const piece = board[from];
112→
113→  // Must have a piece at source
114→  if (piece === 0) {
115→    return { legal: false, reason: 'No piece at source square' };
116→  }
117→
118→  // Must be the correct color's turn
119→  const pieceColor = getPieceColor(piece);
120→  if (pieceColor !== currentTurn) {
121→    return { legal: false, reason: 'Not your piece' };
122→  }
123→
124→  // Can't capture own piece
125→  const targetPiece = board[to];
126→  if (targetPiece !== 0 && getPieceColor(targetPiece) === currentTurn) {
127→    return { legal: false, reason: 'Cannot capture your own piece' };
128→  }
129→
130→  const pieceType = Math.abs(piece);
131→  let isValid = false;
132→
133→  // Dispatch to piece-specific validation
134→  switch (pieceType) {
135→    case PIECE_TYPES.PAWN:
136→      isValid = isValidPawnMove(board, from, to, enPassantTarget);
137→      break;
138→    case PIECE_TYPES.KNIGHT:
139→      isValid = isValidKnightMove(board, from, to);
140→      break;
141→    case PIECE_TYPES.BISHOP:
142→      isValid = isValidBishopMove(board, from, to);
143→      break;
144→    case PIECE_TYPES.ROOK:
145→      isValid = isValidRookMove(board, from, to);
146→      break;
147→    case PIECE_TYPES.QUEEN:
148→      isValid = isValidQueenMove(board, from, to);
149→      break;
150→    case PIECE_TYPES.KING: {
151→      // For castling, check if king has moved AND if rook has moved
152→      const kingHasMoved = movedPieces.has(from);
153→      const { row: fromRow, col: fromCol } = indexToRowCol(from);
154→      const { col: toCol } = indexToRowCol(to);
155→      const colDiff = Math.abs(toCol - fromCol);
156→
157→      if (colDiff === 2 && !kingHasMoved) {
158→        // Castling attempt - also need to check rook hasn't moved
159→        const direction = toCol > fromCol ? 1 : -1;
160→        const rookCol = direction === 1 ? 7 : 0;
161→        const rookIndex = rowColToIndex(fromRow, rookCol);
162→        if (movedPieces.has(rookIndex)) {
163→          return { legal: false, reason: 'Rook has already moved' };
164→        }
165→      }
166→
167→      isValid = isValidKingMove(board, from, to, kingHasMoved);
168→      break;
169→    }
170→  }
171→
172→  if (!isValid) {
173→    return { legal: false, reason: 'Invalid move for this piece' };
174→  }
175→
176→  // Simulate move and check if own king is in check
177→  const testBoard = [...board];
178→  testBoard[to] = piece;
179→  testBoard[from] = 0;
180→
181→  // Handle en passant capture in simulation
182→  if (pieceType === PIECE_TYPES.PAWN && to === enPassantTarget) {
183→    const { row: toRow, col: toCol } = indexToRowCol(to);
184→    const capturedPawnRow = isWhitePiece(piece) ? toRow + 1 : toRow - 1;
185→    testBoard[rowColToIndex(capturedPawnRow, toCol)] = 0;
186→  }
187→
188→  const isWhite = currentTurn === COLORS.WHITE;
189→  if (isKingInCheck(testBoard, isWhite)) {
190→    return { legal: false, reason: 'Move would leave king in check' };
191→  }
192→
193→  // Check promotion requirements
194→  if (needsPromotion(piece, to)) {
195→    if (!promotion) {
196→      return { legal: false, reason: 'Promotion piece required (q, r, b, n)' };
197→    }
198→    const validPromotions = ['q', 'r', 'b', 'n'];
199→    if (!validPromotions.includes(promotion)) {
200→      return { legal: false, reason: 'Invalid promotion piece. Must be q, r, b, or n' };
201→    }
202→  }
203→
204→  return { legal: true };
205→}
206→
207→// --- Generate all legal moves ---
208→
209→function getLegalMoves(gameState) {
210→  const { board, currentTurn } = gameState;
211→  const isWhite = currentTurn === COLORS.WHITE;
212→  const moves = [];
213→
214→  for (let from = 0; from < 64; from++) {
215→    const piece = board[from];
216→    if (piece === 0) continue;
217→    if (isWhite && !isWhitePiece(piece)) continue;
218→    if (!isWhite && !isBlackPiece(piece)) continue;
219→
220→    for (let to = 0; to < 64; to++) {
221→      if (from === to) continue;
222→
223→      // For pawn promotions, try queen promotion as default check
224→      const pieceType = Math.abs(piece);
225→      let promotion = null;
226→      if (pieceType === PIECE_TYPES.PAWN && needsPromotion(piece, to)) {
227→        promotion = 'q'; // Check with queen; other promotions are also legal
228→      }
229→
230→      const result = isMoveLegal(gameState, from, to, promotion);
231→      if (result.legal) {
232→        const uci = indexToAlgebraic(from) + indexToAlgebraic(to);
233→        if (pieceType === PIECE_TYPES.PAWN && needsPromotion(piece, to)) {
234→          // Add all promotion variants
235→          moves.push(uci + 'q');
236→          moves.push(uci + 'r');
237→          moves.push(uci + 'b');
238→          moves.push(uci + 'n');
239→        } else {
240→          moves.push(uci);
241→        }
242→      }
243→    }
244→  }
245→
246→  return moves;
247→}
248→
249→// --- Apply a move to game state (mutates a copy) ---
250→
251→function applyMove(gameState, from, to, promotion) {
252→  const board = [...gameState.board];
253→  const piece = board[from];
254→  const pieceType = Math.abs(piece);
255→  const isWhite = isWhitePiece(piece);
256→  let isCapture = board[to] !== 0;
257→
258→  // Basic move
259→  board[to] = piece;
260→  board[from] = 0;
261→
262→  // Castling: move the rook too
263→  if (pieceType === PIECE_TYPES.KING) {
264→    const { row: fromRow, col: fromCol } = indexToRowCol(from);
265→    const { col: toCol } = indexToRowCol(to);
266→    if (Math.abs(toCol - fromCol) === 2) {
267→      const direction = toCol > fromCol ? 1 : -1;
268→      const rookCol = direction === 1 ? 7 : 0;
269→      const rookIndex = rowColToIndex(fromRow, rookCol);
270→      const newRookIndex = rowColToIndex(fromRow, toCol - direction);
271→      board[newRookIndex] = board[rookIndex];
272→      board[rookIndex] = 0;
273→    }
274→  }
275→
276→  // En passant capture: remove the captured pawn
277→  if (pieceType === PIECE_TYPES.PAWN && to === gameState.enPassantTarget) {
278→    const { row: toRow, col: toCol } = indexToRowCol(to);
279→    const capturedPawnRow = isWhite ? toRow + 1 : toRow - 1;
280→    board[rowColToIndex(capturedPawnRow, toCol)] = 0;
281→    isCapture = true;
282→  }
283→
284→  // Promotion
285→  if (pieceType === PIECE_TYPES.PAWN && needsPromotion(piece, to)) {
286→    const promotionMap = {
287→      'q': PIECE_TYPES.QUEEN,
288→      'r': PIECE_TYPES.ROOK,
289→      'b': PIECE_TYPES.BISHOP,
290→      'n': PIECE_TYPES.KNIGHT
291→    };
292→    const promotedType = promotionMap[promotion] || PIECE_TYPES.QUEEN;
293→    board[to] = isWhite ? promotedType : -promotedType;
294→  }
295→
296→  // Update en passant target
297→  const newEnPassantTarget = getEnPassantTarget(gameState.board, from, to);
298→
299→  // Update moved pieces
300→  const newMovedPieces = new Set(gameState.movedPieces);
301→  newMovedPieces.add(from);
302→
303→  // Update half-move clock
304→  const newHalfMoveClock = (pieceType === PIECE_TYPES.PAWN || isCapture) ? 0 : gameState.halfMoveClock + 1;
305→
306→  // Update position history
307→  const positionKey = generatePositionKey(board);
308→  const newPositionHistory = [...gameState.positionHistory, positionKey];
309→
310→  // Update move history
311→  const moveUci = indexToAlgebraic(from) + indexToAlgebraic(to) + (promotion || '');
312→  const newMoveHistory = [...gameState.moveHistory, moveUci];
313→
314→  // Toggle turn
315→  const nextTurn = gameState.currentTurn === COLORS.WHITE ? COLORS.BLACK : COLORS.WHITE;
316→
317→  return {
318→    board,
319→    currentTurn: nextTurn,
320→    moveHistory: newMoveHistory,
321→    enPassantTarget: newEnPassantTarget,
322→    movedPieces: newMovedPieces,
323→    halfMoveClock: newHalfMoveClock,
324→    positionHistory: newPositionHistory
325→  };
326→}
327→
328→// --- Game result detection (fixes stalemate bug) ---
329→
330→function getGameResult(gameState) {
331→  const { board, currentTurn, halfMoveClock, positionHistory } = gameState;
332→  const isWhite = currentTurn === COLORS.WHITE;
333→
334→  // Check for insufficient material
335→  if (isInsufficientMaterial(board)) {
336→    return { over: true, result: '1/2-1/2', reason: 'insufficient_material' };
337→  }
338→
339→  // 50-move rule (100 half-moves)
340→  if (halfMoveClock >= 100) {
341→    return { over: true, result: '1/2-1/2', reason: 'fifty_move_rule' };
342→  }
343→
344→  // Threefold repetition
345→  const currentPosition = generatePositionKey(board);
346→  const repetitions = positionHistory.filter(p => p === currentPosition).length;
347→  if (repetitions >= 3) {
348→    return { over: true, result: '1/2-1/2', reason: 'threefold_repetition' };
349→  }
350→
351→  // Check legal moves for the side to move
352→  const legalMoves = getLegalMoves(gameState);
353→
354→  if (legalMoves.length === 0) {
355→    // No legal moves — is the king in check?
356→    if (isKingInCheck(board, isWhite)) {
357→      // Checkmate: the other side wins
358→      const winner = isWhite ? '0-1' : '1-0';
359→      return { over: true, result: winner, reason: 'checkmate' };
360→    } else {
361→      // Stalemate
362→      return { over: true, result: '1/2-1/2', reason: 'stalemate' };
363→    }
364→  }
365→
366→  return { over: false };
367→}
368→
369→// --- Initial game state ---
370→
371→function createInitialGameState() {
372→  return {
373→    board: [...INITIAL_BOARD],
374→    currentTurn: COLORS.WHITE,
375→    moveHistory: [],
376→    enPassantTarget: null,
377→    movedPieces: new Set(),
378→    halfMoveClock: 0,
379→    positionHistory: []
380→  };
381→}
382→
383→// --- Serialization for SQLite ---
384→
385→function serializeGameState(gs) {
386→  return {
387→    board: JSON.stringify(gs.board),
388→    current_turn: gs.currentTurn,
389→    move_history: JSON.stringify(gs.moveHistory),
390→    en_passant_target: gs.enPassantTarget,
391→    moved_pieces: JSON.stringify([...gs.movedPieces]),
392→    half_move_clock: gs.halfMoveClock,
393→    position_history: JSON.stringify(gs.positionHistory)
394→  };
395→}
396→
397→function deserializeGameState(row) {
398→  return {
399→    board: JSON.parse(row.board),
400→    currentTurn: row.current_turn,
401→    moveHistory: JSON.parse(row.move_history),
402→    enPassantTarget: row.en_passant_target,
403→    movedPieces: new Set(JSON.parse(row.moved_pieces)),
404→    halfMoveClock: row.half_move_clock,
405→    positionHistory: JSON.parse(row.position_history)
406→  };
407→}
408→
409→module.exports = {
410→  indexToAlgebraic,
411→  algebraicToIndex,
412→  boardToFEN,
413→  parseMove,
414→  isMoveLegal,
415→  getLegalMoves,
416→  applyMove,
417→  getGameResult,
418→  createInitialGameState,
419→  serializeGameState,
420→  deserializeGameState
421→};
