  1→// Piece type constants (0-6)
  2→const PIECE_TYPES = {
  3→  NONE: 0,
  4→  KING: 1,
  5→  PAWN: 2,
  6→  KNIGHT: 3,
  7→  ROOK: 4,
  8→  BISHOP: 5,
  9→  QUEEN: 6
 10→};
 11→
 12→// Color constants
 13→const COLORS = {
 14→  WHITE: 'white',
 15→  BLACK: 'black'
 16→};
 17→
 18→// White pieces (positive numbers 1-6)
 19→const WHITE_PIECES = {
 20→  KING: 1,
 21→  PAWN: 2,
 22→  KNIGHT: 3,
 23→  ROOK: 4,
 24→  BISHOP: 5,
 25→  QUEEN: 6
 26→};
 27→
 28→// Black pieces (negative numbers -1 to -6)
 29→const BLACK_PIECES = {
 30→  KING: -1,
 31→  PAWN: -2,
 32→  KNIGHT: -3,
 33→  ROOK: -4,
 34→  BISHOP: -5,
 35→  QUEEN: -6
 36→};
 37→
 38→// Helper function to get piece color
 39→const getPieceColor = (piece) => {
 40→  if (piece > 0) return COLORS.WHITE;
 41→  if (piece < 0) return COLORS.BLACK;
 42→  return null;
 43→};
 44→
 45→// Helper function to get piece type
 46→const getPieceType = (piece) => {
 47→  return Math.abs(piece);
 48→};
 49→
 50→// Helper function to check if piece is white
 51→const isWhitePiece = (piece) => piece > 0;
 52→
 53→// Helper function to check if piece is black
 54→const isBlackPiece = (piece) => piece < 0;
 55→
 56→// Standard starting position in FEN notation
 57→const STARTING_FEN = 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR';
 58→
 59→// FEN character to piece number mapping
 60→const FEN_TO_PIECE = {
 61→  'K': 1,   // White King
 62→  'P': 2,   // White Pawn
 63→  'N': 3,   // White Knight
 64→  'R': 4,   // White Rook
 65→  'B': 5,   // White Bishop
 66→  'Q': 6,   // White Queen
 67→  'k': -1,  // Black King
 68→  'p': -2,  // Black Pawn
 69→  'n': -3,  // Black Knight
 70→  'r': -4,  // Black Rook
 71→  'b': -5,  // Black Bishop
 72→  'q': -6,  // Black Queen
 73→};
 74→
 75→// Piece number to FEN character mapping (reverse of FEN_TO_PIECE)
 76→const PIECE_TO_FEN = {};
 77→for (const [char, num] of Object.entries(FEN_TO_PIECE)) {
 78→  PIECE_TO_FEN[num] = char;
 79→}
 80→
 81→// Parse FEN notation to board array
 82→const parseFEN = (fen) => {
 83→  const board = new Array(64).fill(0);
 84→  const ranks = fen.split('/');
 85→
 86→  let squareIndex = 0;
 87→
 88→  for (let rank of ranks) {
 89→    for (let char of rank) {
 90→      if (isNaN(char)) {
 91→        board[squareIndex] = FEN_TO_PIECE[char];
 92→        squareIndex++;
 93→      } else {
 94→        const emptySquares = parseInt(char);
 95→        squareIndex += emptySquares;
 96→      }
 97→    }
 98→  }
 99→
100→  return board;
101→};
102→
103→// Initial chess board state (64 squares, 0-63)
104→const INITIAL_BOARD = parseFEN(STARTING_FEN);
105→
106→module.exports = {
107→  PIECE_TYPES,
108→  COLORS,
109→  WHITE_PIECES,
110→  BLACK_PIECES,
111→  getPieceColor,
112→  getPieceType,
113→  isWhitePiece,
114→  isBlackPiece,
115→  STARTING_FEN,
116→  FEN_TO_PIECE,
117→  PIECE_TO_FEN,
118→  parseFEN,
119→  INITIAL_BOARD
120→};
