  1→import { useCallback } from 'react';
  2→import { encodeFunctionData } from 'viem';
  3→import { formatMoves } from './usePublishGame';
  4→import { chessLedgerAbi, CHESS_LEDGER_ADDRESS } from '../contracts/chessLedgerAbi';
  5→
  6→const API_BASE = 'http://localhost:3000';
  7→
  8→// --- Helpers (ported from demo.html) ---
  9→
 10→function bufToHex(buf) {
 11→  return '0x' + Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
 12→}
 13→
 14→function hexToBytes(hex) {
 15→  hex = hex.startsWith('0x') ? hex.slice(2) : hex;
 16→  const bytes = new Uint8Array(hex.length / 2);
 17→  for (let i = 0; i < hex.length; i += 2) {
 18→    bytes[i / 2] = parseInt(hex.substr(i, 2), 16);
 19→  }
 20→  return bytes;
 21→}
 22→
 23→function parseDERSignature(signatureBytes) {
 24→  const sig = new Uint8Array(signatureBytes);
 25→  let offset = 0;
 26→
 27→  if (sig[offset++] !== 0x30) throw new Error('Invalid DER: missing SEQUENCE tag');
 28→  let totalLen = sig[offset++];
 29→  if (totalLen & 0x80) {
 30→    const numLenBytes = totalLen & 0x7f;
 31→    offset += numLenBytes;
 32→  }
 33→
 34→  // R
 35→  if (sig[offset++] !== 0x02) throw new Error('Invalid DER: missing INTEGER tag for r');
 36→  const rLen = sig[offset++];
 37→  let rBytes = sig.slice(offset, offset + rLen);
 38→  offset += rLen;
 39→  while (rBytes.length > 32 && rBytes[0] === 0x00) rBytes = rBytes.slice(1);
 40→  if (rBytes.length < 32) {
 41→    const padded = new Uint8Array(32);
 42→    padded.set(rBytes, 32 - rBytes.length);
 43→    rBytes = padded;
 44→  }
 45→
 46→  // S
 47→  if (sig[offset++] !== 0x02) throw new Error('Invalid DER: missing INTEGER tag for s');
 48→  const sLen = sig[offset++];
 49→  let sBytes = sig.slice(offset, offset + sLen);
 50→  while (sBytes.length > 32 && sBytes[0] === 0x00) sBytes = sBytes.slice(1);
 51→  if (sBytes.length < 32) {
 52→    const padded = new Uint8Array(32);
 53→    padded.set(sBytes, 32 - sBytes.length);
 54→    sBytes = padded;
 55→  }
 56→
 57→  return { r: bufToHex(rBytes), s: bufToHex(sBytes) };
 58→}
 59→
 60→// --- Hook ---
 61→
 62→export function usePasskeyPublish({ account, credentialId, rawId }) {
 63→  const publishGame = useCallback(async (game) => {
 64→    if (!account || !rawId) {
 65→      return { published: false, reason: 'passkey-not-authenticated' };
 66→    }
 67→    if (!CHESS_LEDGER_ADDRESS) {
 68→      return { published: false, reason: 'no-contract-address' };
 69→    }
 70→
 71→    try {
 72→      // 1. Encode ChessLedger.publishGame calldata
 73→      const movesString = formatMoves(game.moveHistory || []);
 74→      const calldata = encodeFunctionData({
 75→        abi: chessLedgerAbi,
 76→        functionName: 'publishGame',
 77→        args: [game.id, game.result, movesString, game.engineColor],
 78→      });
 79→
 80→      // 2. Get challenge from server
 81→      const challengeResp = await fetch(`${API_BASE}/api/get-challenge-v2`, {
 82→        method: 'POST',
 83→        headers: { 'Content-Type': 'application/json' },
 84→        body: JSON.stringify({
 85→          proxyAddr: account,
 86→          target: CHESS_LEDGER_ADDRESS,
 87→          value: '0',
 88→          data: calldata,
 89→        }),
 90→      });
 91→      const challengeData = await challengeResp.json();
 92→      if (!challengeResp.ok) throw new Error(challengeData.error || 'Failed to get challenge');
 93→
 94→      const challengeBytes = hexToBytes(challengeData.challenge);
 95→
 96→      // 3. Sign with passkey (raw challenge bytes — NOT base64)
 97→      const assertion = await navigator.credentials.get({
 98→        publicKey: {
 99→          challenge: challengeBytes,
100→          rpId: location.hostname,
101→          allowCredentials: [{ type: 'public-key', id: rawId }],
102→          userVerification: 'preferred',
103→          timeout: 60000,
104→        },
105→      });
106→
107→      // 4. Extract signature fields
108→      const authenticatorData = bufToHex(assertion.response.authenticatorData);
109→      const clientDataJSON = new TextDecoder().decode(assertion.response.clientDataJSON);
110→      const { r, s } = parseDERSignature(new Uint8Array(assertion.response.signature));
111→      const typeIndex = clientDataJSON.indexOf('"type":"webauthn.get"');
112→      const challengeIndex = clientDataJSON.indexOf('"challenge":"');
113→
114→      // 5. Submit signed transaction
115→      const submitResp = await fetch(`${API_BASE}/api/submit-execution-v2`, {
116→        method: 'POST',
117→        headers: { 'Content-Type': 'application/json' },
118→        body: JSON.stringify({
119→          proxyAddr: account,
120→          target: CHESS_LEDGER_ADDRESS,
121→          value: '0',
122→          data: calldata,
123→          auth: { authenticatorData, clientDataJSON, challengeIndex, typeIndex, r, s },
124→        }),
125→      });
126→      const txData = await submitResp.json();
127→      if (!submitResp.ok) throw new Error(txData.error || 'Failed to submit transaction');
128→
129→      return { published: true, txHash: txData.txHash };
130→    } catch (err) {
131→      console.error('Passkey publish failed:', err);
132→      return { published: false, reason: 'tx-failed', error: err };
133→    }
134→  }, [account, credentialId, rawId]);
135→
136→  return { publishGame };
137→}
