406→          }
407→        }
408→
409→        // Handle en passant
410→        if (pieceType === PIECE_TYPES.PAWN && move.to === enPassantTarget) {
411→          const { row: toRow, col: toCol } = indexToRowCol(move.to);
412→          const isWhite = piece > 0;
413→          const capturedPawnRow = isWhite ? toRow + 1 : toRow - 1;
